effect.shader:
float gmHash21(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
vec2 gmEdge(vec2 uv) {
if (edgeMode == 1) {
return 1.0 - abs(mod(uv, 2.0) - 1.0);
}
if (edgeMode == 2) {
return fract(uv);
}
return clamp(uv, 0.0, 1.0);
}
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
float safeBlock = max(blockSizePx, 1.0);
vec2 cell = floor(uv * texSize / safeBlock);
float framePhase = floor(evolution * 12.0 + (autoAnimate ? acTime * speed * 12.0 : 0.0));
vec2 phaseCell = cell + vec2(framePhase * 0.071, framePhase * 0.113) + seed * vec2(1.73, 2.37);
float blockGate = step(1.0 - corruption, gmHash21(phaseCell + vec2(5.1, 9.7)));
float randomAngle = gmHash21(phaseCell + vec2(17.3, 2.9)) * 6.28318530718;
vec2 randomDirection = vec2(cos(randomAngle), sin(randomAngle));
vec2 chosenDirection = vec2(cos(angle), sin(angle));
vec2 flowDirection = normalize(mix(randomDirection, chosenDirection, directionality) + vec2(0.00001));
float randomMagnitude = 0.25 + 0.75 * gmHash21(phaseCell + vec2(11.9, 23.7));
vec2 motion = flowDirection * motionPx * randomMagnitude * blockGate / texSize;
vec4 src = texture2DCv(inputImg.texture, uv);
vec4 accumulated = vec4(0.0);
float weight = 1.0;
float weightSum = 0.0;
for (int i = 0; i < 8; i++) {
float t = float(i) / 7.0;
vec2 sampleUv = gmEdge(uv + motion * (1.0 + t * smear));
accumulated += texture2DCv(inputImg.texture, sampleUv) * weight;
weightSum += weight;
weight *= decay;
}
vec4 shifted = accumulated / max(weightSum, 0.0001);
vec2 chromaOffset = flowDirection * chromaPx * blockGate / texSize;
vec4 redSample = texture2DCv(inputImg.texture, gmEdge(uv + motion + chromaOffset));
vec4 blueSample = texture2DCv(inputImg.texture, gmEdge(uv + motion - chromaOffset));
vec3 moshRgb = vec3(redSample.r, shifted.g, blueSample.b);
float localMix = clamp(mixAmount * blockGate, 0.0, 1.0);
gl_FragColor = vec4(mix(src.rgb, moshRgb, localMix), src.a);
}
